import type { EngineCatalogEntry, EngineOrigin } from '../types/catalog.ts';
import type { Aspiration, EngineCategory, EngineProfile } from '../types/profile.ts';

/**
 * Fun packs: engines generated by the REVLINE voice synthesiser (src/audio/placeholder/voices.ts).
 * No recordings and no brand names: every sound is made in code. One row = one engine; the
 * gearing is derived from the top speed at the limiter in the top gear.
 */
interface FunRow {
  id: string;
  voice: string;
  pack: string;
  name: string;
  origin: EngineOrigin;
  en: string;
  cs: string;
  tags: readonly string[];
  category?: EngineCategory;
  cylinders?: number;
  litres?: number | null;
  aspiration?: Aspiration;
  idle: number;
  redline: number;
  ratios: readonly number[];
  topKmh: number;
  pops?: number;
  bark?: number;
  volume?: number;
  /** Slow, heavy machines (locomotives) react slower. */
  heavy?: boolean;
}

