function wheelRpmAt(kmh: number): number {
  return ((kmh / 3.6) / (2 * Math.PI * TIRE)) * 60;
}

function toProfile(r: FunRow): EngineProfile {
  const limiter = Math.round(r.redline * 1.03);
  const ratios = [...r.ratios];
  const last = ratios[ratios.length - 1] as number;
  const finalDrive = Math.round((limiter / (wheelRpmAt(r.topKmh) * last)) * 100) / 100;
  const span = r.redline - r.idle;
  return {
    id: r.id,
    name: r.name,
    description: r.en,
    category: r.category ?? 'Unknown',
    aspiration: r.aspiration ?? 'naturally-aspirated',
    cylinders: r.cylinders ?? 1,
    displacementL: r.litres ?? null,
    source: { configLabel: 'REVLINE voice synth', soundName: `voice:${r.voice}`, awc: '', audioConfig: [] },
    idleRPM: r.idle,
    redlineRPM: r.redline,
    limiterRPM: limiter,
    gearbox: {
      gearRatios: ratios,
      finalDrive,
      tireRadiusM: TIRE,
      shiftUpRPM: { gentle: Math.round(r.idle + span * 0.3), hard: r.redline - 150 },
      shiftDownRPM: { gentle: Math.round(Math.min(r.idle * 1.25, r.idle + span * 0.15)), hard: Math.round(r.idle + span * 0.45) },
      shiftDuration: 0.3,
      minShiftInterval: 0.9,
      launchRPM: Math.round(r.idle + span * (ratios.length === 1 ? 0.12 : 0.35)),
    },
    dynamics: { engineResponse: r.heavy ? 0.25 : 0.08, throttleSensitivity: 1, fullThrottleAccel: r.heavy ? 3 : 4 },
    audio: {
      converted: false,
      manifest: '',
      volume: r.volume ?? 1,
      pitch: 1,
      overrunPops: r.pops ?? 0,
      shiftBark: r.bark ?? 0,
      turbo: 0,
      voice: r.voice,
      placeholderTone: { brightness: 0.5, roughness: 0.3 },
    },
  };
}

export const FUN_PROFILES: readonly EngineProfile[] = ROWS.map(toProfile);

export const FUN_CATALOG: readonly EngineCatalogEntry[] = ROWS.map((r) => ({
  id: r.id, displayName: r.name, origin: r.origin, shortDescription: { en: r.en, cs: r.cs }, tags: r.tags, tier: 'pack', packId: r.pack,
}));
